import{_ as s,o as e,c as i,a2 as a}from"./chunks/framework.vLhlLNVn.js";const k=JSON.parse('{"title":"Authentication","description":"","frontmatter":{},"headers":[],"relativePath":"api-reference/authentication.md","filePath":"api-reference/authentication.md"}'),d={name:"api-reference/authentication.md"};function o(n,t,h,r,l,c){return e(),i("div",null,[...t[0]||(t[0]=[a(`<h1 id="authentication" tabindex="-1">Authentication <a class="header-anchor" href="#authentication" aria-label="Permalink to &quot;Authentication&quot;">​</a></h1><p>Every method throws <a href="/introduction/errors.html"><code>SkapiError</code></a> with <code>.code</code> and <code>.message</code>. Methods that need a signed-in user throw <code>INVALID_REQUEST</code> (<code>User login is required.</code>) without one, and any method can throw <code>NETWORK_ERROR</code> when no answer comes back.</p><p>Values that fail a check throw <code>INVALID_PARAMETER</code> before anything is sent. The common messages:</p><table tabindex="0"><thead><tr><th>field</th><th>message</th></tr></thead><tbody><tr><td><code>email</code></td><td><code>&quot;email&quot; is required.</code> / <code>&quot;email&quot; should be at least 5 characters.</code> / <code>&quot;&lt;value&gt;&quot; is an invalid email.</code></td></tr><tr><td><code>password</code></td><td><code>&quot;password&quot; is required.</code> / <code>&quot;password&quot; should be at least 6 characters.</code> / <code>&quot;password&quot; can be up to 60 characters max.</code></td></tr><tr><td><code>phone_number</code></td><td><code>&quot;phone_number&quot; is invalid. The format should be &quot;+00123456789&quot;. Type: string.</code></td></tr><tr><td><code>birthdate</code></td><td><code>&quot;birthdate&quot; is invalid. The format should be &quot;yyyy-mm-dd&quot;. Type: string.</code></td></tr><tr><td><code>picture</code>, <code>profile</code>, <code>website</code>, redirect URLs</td><td><code>&quot;&lt;value&gt;&quot; is an invalid url.</code> (a full URL with scheme and host is required)</td></tr><tr><td>text fields</td><td><code>&lt;value&gt; is invalid in &quot;&lt;field&gt;&quot;. allowed type or value is: Type&lt;string&gt;.</code></td></tr></tbody></table><h2 id="signup" tabindex="-1">signup <a class="header-anchor" href="#signup" aria-label="Permalink to &quot;signup&quot;">​</a></h2><div class="language-swift vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">swift</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">func</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> signup</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">_</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> params: JSON, </span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">option</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: JSON</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">?</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> =</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> nil</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">) </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">async</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> throws</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> -&gt;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> JSON</span></span></code></pre></div><p>Creates an account. Logs out the user signed in on this object first.</p><p><code>params</code>:</p><table tabindex="0"><thead><tr><th>key</th><th>type</th><th></th></tr></thead><tbody><tr><td><code>email</code></td><td>string</td><td>required</td></tr><tr><td><code>password</code></td><td>string</td><td>required, 6 to 60 characters</td></tr><tr><td><code>username</code></td><td>string</td><td>optional permanent login ID; the e-mail logs in too once verified</td></tr><tr><td><code>name</code>, <code>nickname</code>, <code>given_name</code>, <code>middle_name</code>, <code>family_name</code>, <code>gender</code>, <code>misc</code></td><td>string</td><td></td></tr><tr><td><code>birthdate</code></td><td>string</td><td><code>&quot;yyyy-mm-dd&quot;</code></td></tr><tr><td><code>phone_number</code></td><td>string</td><td><code>&quot;+&quot;</code> and digits</td></tr><tr><td><code>address</code></td><td>string or object</td><td></td></tr><tr><td><code>picture</code>, <code>profile</code>, <code>website</code></td><td>string</td><td>full URL</td></tr><tr><td><code>email_public</code>, <code>phone_number_public</code>, <code>address_public</code>, <code>gender_public</code>, <code>birthdate_public</code></td><td>bool</td><td>default <code>false</code></td></tr></tbody></table><p><code>option</code>:</p><table tabindex="0"><thead><tr><th>key</th><th>type</th><th></th></tr></thead><tbody><tr><td><code>signup_confirmation</code></td><td>bool or string</td><td><code>true</code> sends a confirmation link the user must open before logging in. A full URL also does, and the link leads there after confirming. Default <code>false</code>.</td></tr><tr><td><code>login</code></td><td>bool</td><td>log in right after signup and return the profile. Not with <code>signup_confirmation</code>.</td></tr><tr><td><code>email_subscription</code></td><td>bool, number or string</td><td>subscribes the user to a newsletter once they confirm. Needs <code>signup_confirmation</code>.</td></tr><tr><td><code>template</code></td><td>object</td><td><code>[&quot;signup_confirmation&quot;: &quot;&lt;message_id&gt;&quot;, &quot;welcome&quot;: &quot;&lt;message_id&gt;&quot;]</code>: uploaded templates for this call</td></tr></tbody></table><p>Returns a <code>JSON</code> string, <code>&quot;SUCCESS: The account has been created.&quot;</code> or <code>&quot;SUCCESS: The account has been created. User&#39;s signup confirmation is required.&quot;</code> with <code>signup_confirmation</code>, or the <a href="/authentication/profile.html#profile-fields">profile</a> object with <code>login</code>. See <a href="/authentication/signup.html">Signing Up Users</a>.</p><h3 id="errors" tabindex="-1">Errors <a class="header-anchor" href="#errors" aria-label="Permalink to &quot;Errors&quot;">​</a></h3><table tabindex="0"><thead><tr><th>code</th><th>message</th></tr></thead><tbody><tr><td><code>EXISTS</code></td><td><code>The account already exists.</code></td></tr><tr><td><code>INVALID_PARAMETER</code></td><td><code>Key &quot;email&quot; is required.</code> / <code>Key &quot;password&quot; is required.</code></td></tr><tr><td><code>INVALID_PARAMETER</code></td><td><code>&quot;address&quot; should be type: &lt;string | dict&gt;.</code></td></tr><tr><td><code>INVALID_PARAMETER</code></td><td><code>Invalid password. Password must be at least 6 characters.</code></td></tr><tr><td><code>INVALID_PARAMETER</code></td><td><code>&quot;option.signup_confirmation&quot; should be type: &lt;string | boolean&gt;.</code></td></tr><tr><td><code>INVALID_PARAMETER</code></td><td><code>&quot;login&quot; is not allowed when &quot;option.signup_confirmation&quot; is true.</code> / <code>&quot;option.login&quot; should be type: boolean.</code></td></tr><tr><td><code>INVALID_PARAMETER</code></td><td><code>&quot;option.signup_confirmation&quot; should be true if &quot;email_public&quot; is set to true.</code></td></tr><tr><td><code>INVALID_PARAMETER</code></td><td><code>&quot;option.signup_confirmation&quot; is required for email subscription.</code></td></tr><tr><td><code>INVALID_PARAMETER</code></td><td><code>&quot;option.signup_confirmation&quot; is required when &quot;option.template.signup_confirmation&quot; is set.</code></td></tr><tr><td><code>INVALID_PARAMETER</code></td><td><code>&quot;option.template&quot; should be type: &lt;object&gt;.</code> / <code>&quot;option.template.&lt;key&gt;&quot; should be a non-empty &lt;string&gt; (template message_id).</code></td></tr><tr><td><code>REQUEST_EXCEED</code></td><td><code>Too many attempts. Please try again later.</code></td></tr><tr><td><code>CODE_DELIVERY_FAILURE</code></td><td><code>Failed to deliver verification code.</code></td></tr><tr><td><code>INVALID_REQUEST</code></td><td>the server&#39;s reason</td></tr></tbody></table><h2 id="resendsignupconfirmation" tabindex="-1">resendSignupConfirmation <a class="header-anchor" href="#resendsignupconfirmation" aria-label="Permalink to &quot;resendSignupConfirmation&quot;">​</a></h2><div class="language-swift vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">swift</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">func</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> resendSignupConfirmation</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">() </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">async</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> throws</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> -&gt;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> JSON</span></span></code></pre></div><p>Sends the signup confirmation e-mail again. Works after <code>login</code> threw <code>SIGNUP_CONFIRMATION_NEEDED</code>, or after <code>signup</code> with <code>signup_confirmation</code>, on the same object. Returns the server&#39;s message.</p><table tabindex="0"><thead><tr><th>code</th><th>message</th></tr></thead><tbody><tr><td><code>INVALID_REQUEST</code></td><td><code>Least one login attempt is required.</code></td></tr></tbody></table><h2 id="login" tabindex="-1">login <a class="header-anchor" href="#login" aria-label="Permalink to &quot;login&quot;">​</a></h2><div class="language-swift vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">swift</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">func</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> login</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">email</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">String</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">?</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> =</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> nil</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">username</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">String</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">?</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> =</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> nil</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">password</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">String</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">) </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">async</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> throws</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> -&gt;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> JSON</span></span></code></pre></div><p>Signs in and returns the <a href="/authentication/profile.html#profile-fields">profile</a>. The e-mail is matched without regard to case. An <code>email</code> that is not an e-mail address is read as a username. The password is never sent: sign-in proves it with a secure exchange. The session is saved to <code>storage</code>. See <a href="/authentication/login.html">Login / Logout</a>.</p><h3 id="errors-1" tabindex="-1">Errors <a class="header-anchor" href="#errors-1" aria-label="Permalink to &quot;Errors&quot;">​</a></h3><table tabindex="0"><thead><tr><th>code</th><th>message</th></tr></thead><tbody><tr><td><code>INCORRECT_USERNAME_OR_PASSWORD</code></td><td><code>Incorrect username or password.</code></td></tr><tr><td><code>SIGNUP_CONFIRMATION_NEEDED</code></td><td><code>User&#39;s signup confirmation is required.</code></td></tr><tr><td><code>USER_IS_DISABLED</code></td><td><code>This account is disabled.</code></td></tr><tr><td><code>MFA_REQUIRED</code></td><td><code>A code from the authenticator app is required to sign in. Call verifyMFA() with the code.</code></td></tr><tr><td><code>REQUEST_EXCEED</code></td><td><code>Too many attempts. Please try again later.</code></td></tr><tr><td><code>INVALID_PARAMETER</code></td><td><code>At least one of &quot;username&quot; or &quot;email&quot; is required.</code></td></tr><tr><td><code>INVALID_REQUEST</code></td><td><code>Sign-in codes by SMS are not supported.</code> / <code>The account must set up an authenticator app before signing in.</code></td></tr></tbody></table><h2 id="verifymfa" tabindex="-1">verifyMFA <a class="header-anchor" href="#verifymfa" aria-label="Permalink to &quot;verifyMFA&quot;">​</a></h2><div class="language-swift vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">swift</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">func</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> verifyMFA</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">code</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">String</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">) </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">async</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> throws</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> -&gt;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> JSON</span></span></code></pre></div><p>Finishes a <code>login</code> or <code>openIdLogin</code> that threw <code>MFA_REQUIRED</code>, with the 6 digit code from the authenticator app (spaces are ignored). Call it on the same object within 3 minutes. Returns the profile. See <a href="/authentication/mfa.html">Two-Step Login</a>.</p><table tabindex="0"><thead><tr><th>code</th><th>message</th></tr></thead><tbody><tr><td><code>INVALID_CODE</code></td><td><code>Incorrect authenticator code.</code> / <code>This authenticator code was already used. Wait for the next code.</code> (retry with the next code)</td></tr><tr><td><code>INVALID_REQUEST</code></td><td><code>No sign-in is waiting for an authenticator code. Call login() first.</code></td></tr><tr><td><code>INVALID_REQUEST</code></td><td><code>The sign-in has expired. Call login() again.</code></td></tr><tr><td><code>INVALID_PARAMETER</code></td><td><code>&quot;code&quot; should be the 6 digit code from the authenticator app.</code></td></tr><tr><td><code>REQUEST_EXCEED</code></td><td><code>Too many attempts. Please try again later.</code></td></tr></tbody></table><h2 id="logout" tabindex="-1">logout <a class="header-anchor" href="#logout" aria-label="Permalink to &quot;logout&quot;">​</a></h2><div class="language-swift vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">swift</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">func</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> logout</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">global</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">Bool</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> =</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> false</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">) </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">async</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> throws</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> -&gt;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> String</span></span></code></pre></div><p>Signs out and removes the session from <code>storage</code>. <code>global: true</code> also ends every session of the account on every device. On an anonymous account it deletes the account. With encryption on, the key this device remembers is removed. Returns <code>&quot;SUCCESS: The user has been logged out.&quot;</code></p><h2 id="getprofile" tabindex="-1">getProfile <a class="header-anchor" href="#getprofile" aria-label="Permalink to &quot;getProfile&quot;">​</a></h2><div class="language-swift vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">swift</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">func</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> getProfile</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">refreshToken</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">Bool</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> =</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> false</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">) </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">async</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> -&gt;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> JSON</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">?</span></span></code></pre></div><p>The signed-in user&#39;s profile, or <code>nil</code>. <code>refreshToken: true</code> gets fresh tokens from the server first and returns <code>nil</code> if that fails. It does not throw.</p><h2 id="user" tabindex="-1">user <a class="header-anchor" href="#user" aria-label="Permalink to &quot;user&quot;">​</a></h2><div class="language-swift vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">swift</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">var</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> user: JSON</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">?</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> { </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">get</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> async }</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">var</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> session: SkapiSession</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">?</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> { </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">get</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> async }</span></span></code></pre></div><p><code>await skapi.user</code> is the signed-in user&#39;s profile (a copy), or <code>nil</code>. The first read restores a session saved in <code>storage</code>.</p><p><code>await skapi.session</code> holds the tokens:</p><table tabindex="0"><thead><tr><th>property</th><th></th></tr></thead><tbody><tr><td><code>idToken.jwtToken</code></td><td>the ID token</td></tr><tr><td><code>accessToken.jwtToken</code></td><td>the access token</td></tr><tr><td><code>refreshToken</code></td><td>the refresh token</td></tr></tbody></table><p>Each <code>JwtToken</code> also has <code>payload</code> (the token&#39;s claims, a <code>JSONObject</code>), <code>expiration</code> and <code>issuedAt</code> (seconds).</p><h2 id="loginwithtoken" tabindex="-1">loginWithToken <a class="header-anchor" href="#loginwithtoken" aria-label="Permalink to &quot;loginWithToken&quot;">​</a></h2><div class="language-swift vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">swift</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">func</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> loginWithToken</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">idToken</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">String</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">accessToken</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">String</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">refreshToken</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">String</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">) </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">async</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> throws</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> -&gt;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> JSON</span></span></code></pre></div><p>Takes over the tokens of a sign-in made elsewhere and returns the profile read from the ID token. All three tokens are required; the object is then signed in as that user and the tokens are saved to <code>storage</code>. The token&#39;s signature is not checked locally; the server checks it on each request.</p><table tabindex="0"><thead><tr><th>code</th><th>message</th></tr></thead><tbody><tr><td><code>INVALID_PARAMETER</code></td><td><code>&quot;idToken&quot; is required.</code> / <code>&quot;accessToken&quot; is required.</code> / <code>&quot;refreshToken&quot; is required.</code></td></tr><tr><td><code>INVALID_REQUEST</code></td><td><code>Token does not belong to this service.</code> / <code>Token has expired.</code></td></tr></tbody></table><h2 id="updateprofile" tabindex="-1">updateProfile <a class="header-anchor" href="#updateprofile" aria-label="Permalink to &quot;updateProfile&quot;">​</a></h2><div class="language-swift vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">swift</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">func</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> updateProfile</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">_</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> params: JSON) </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">async</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> throws</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> -&gt;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> JSON</span></span></code></pre></div><p>Changes the signed-in user&#39;s own profile and returns the updated profile. Takes the same profile keys as <a href="#signup">signup</a> except <code>password</code> and <code>username</code>. <code>&quot;&quot;</code> clears a field (not <code>email</code>). The <code>*_public</code> flags must be bools. Other keys are ignored; with nothing to change, it returns the profile without a request. A changed <code>email</code> becomes unverified. See <a href="/authentication/profile.html">User Profile</a>.</p><table tabindex="0"><thead><tr><th>code</th><th>message</th></tr></thead><tbody><tr><td><code>INVALID_REQUEST</code></td><td><code>Anonymous accounts cannot edit their profile.</code></td></tr><tr><td><code>INVALID_REQUEST</code></td><td><code>User&#39;s e-mail should be verified to set &quot;email_public&quot; to true.</code></td></tr><tr><td><code>INVALID_PARAMETER</code></td><td><code>&lt;value&gt; is invalid in &quot;&lt;flag&gt;&quot;. allowed type or value is: Type&lt;boolean&gt;.</code></td></tr><tr><td>the server&#39;s code</td><td>the server&#39;s message, when it refuses the change</td></tr></tbody></table><h2 id="changepassword" tabindex="-1">changePassword <a class="header-anchor" href="#changepassword" aria-label="Permalink to &quot;changePassword&quot;">​</a></h2><div class="language-swift vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">swift</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">func</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> changePassword</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">currentPassword</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">String</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">newPassword</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">String</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">) </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">async</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> throws</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> -&gt;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> String</span></span></code></pre></div><p>Returns <code>&quot;SUCCESS: Password has been changed.&quot;</code> With encryption on, the keyring gets a wrap under the new password first. See <a href="/authentication/password.html">Passwords</a>.</p><table tabindex="0"><thead><tr><th>code</th><th>message</th></tr></thead><tbody><tr><td><code>INVALID_REQUEST</code></td><td><code>Incorrect password.</code></td></tr><tr><td><code>INVALID_REQUEST</code></td><td><code>Anonymous accounts cannot change their password.</code></td></tr><tr><td><code>INVALID_PARAMETER</code></td><td><code>&quot;current_password&quot; is required to change password.</code> / <code>&quot;new_password&quot; is required to change password.</code></td></tr><tr><td><code>INVALID_PARAMETER</code></td><td><code>&quot;new_password&quot; should be at least 6 characters.</code> / <code>&quot;new_password&quot; can be up to 60 characters max.</code> (the same for <code>current_password</code>)</td></tr><tr><td><code>INVALID_PARAMETER</code></td><td><code>Invalid password parameter.</code></td></tr><tr><td><code>REQUEST_EXCEED</code></td><td><code>Too many attempts. Please try again later.</code></td></tr><tr><td><code>ENCRYPTION_LOCKED</code></td><td>encryption is on and locked; the password is not changed</td></tr></tbody></table><h2 id="forgotpassword" tabindex="-1">forgotPassword <a class="header-anchor" href="#forgotpassword" aria-label="Permalink to &quot;forgotPassword&quot;">​</a></h2><div class="language-swift vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">swift</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">func</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> forgotPassword</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">email</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">String</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">template</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: JSON</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">?</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> =</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> nil</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">) </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">async</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> throws</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> -&gt;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> String</span></span></code></pre></div><p>E-mails a password reset code. <code>template: [&quot;forgot_password&quot;: &quot;&lt;message_id&gt;&quot;]</code> uses an uploaded template for this call. Returns <code>&quot;SUCCESS: Verification code has been sent.&quot;</code></p><table tabindex="0"><thead><tr><th>code</th><th>message</th></tr></thead><tbody><tr><td><code>NOT_EXISTS</code></td><td>the server&#39;s message</td></tr><tr><td><code>INVALID_REQUEST</code></td><td>the server&#39;s message, for example <code>User password cannot be reset in the current state.</code></td></tr><tr><td><code>REQUEST_EXCEED</code></td><td>the server&#39;s message, for example <code>Attempt limit exceeded, please try after some time.</code></td></tr><tr><td><code>CODE_DELIVERY_FAILURE</code></td><td>the server&#39;s message</td></tr><tr><td><code>INVALID_PARAMETER</code></td><td><code>&quot;template&quot; should be type: &lt;object&gt;.</code> / <code>&quot;template.forgot_password&quot; should be a non-empty &lt;string&gt; (template message_id).</code></td></tr></tbody></table><h2 id="resetpassword" tabindex="-1">resetPassword <a class="header-anchor" href="#resetpassword" aria-label="Permalink to &quot;resetPassword&quot;">​</a></h2><div class="language-swift vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">swift</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">func</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> resetPassword</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">email</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">String</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">code</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">String</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">newPassword</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">String</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">) </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">async</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> throws</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> -&gt;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> String</span></span></code></pre></div><p>Sets a new password with the code from <code>forgotPassword</code>. Returns <code>&quot;SUCCESS: New password has been set.&quot;</code> A wrong or expired code throws the server&#39;s code and message, for example <code>CodeMismatchException</code>.</p><h2 id="verifyemail" tabindex="-1">verifyEmail <a class="header-anchor" href="#verifyemail" aria-label="Permalink to &quot;verifyEmail&quot;">​</a></h2><div class="language-swift vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">swift</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">func</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> verifyEmail</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">code</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">String</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">?</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> =</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> nil</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">template</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: JSON</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">?</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> =</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> nil</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">) </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">async</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> throws</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> -&gt;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> String</span></span></code></pre></div><p>Without <code>code</code>, e-mails a verification code and returns <code>&quot;SUCCESS: Verification code has been sent.&quot;</code> With <code>code</code>, verifies the e-mail and returns <code>SUCCESS: &quot;email&quot; is verified.</code>, which is also returned at once when the e-mail is already verified. <code>template: [&quot;verification&quot;: &quot;&lt;message_id&gt;&quot;]</code> uses an uploaded template for the code e-mail. See <a href="/authentication/email-verification.html">E-Mail Verification</a>.</p><table tabindex="0"><thead><tr><th>code</th><th>message</th></tr></thead><tbody><tr><td><code>INVALID_REQUEST</code></td><td><code>The user has to be logged in.</code> / <code>No e-mail to verify</code></td></tr><tr><td><code>INVALID_REQUEST</code></td><td><code>Anonymous accounts cannot verify an e-mail.</code></td></tr><tr><td><code>INVALID_PARAMETER</code></td><td><code>&quot;template.verification&quot; should be a non-empty &lt;string&gt; (template message_id).</code></td></tr><tr><td><code>CodeMismatchException</code></td><td><code>Invalid verification code provided, please try again.</code></td></tr><tr><td><code>LimitExceededException</code></td><td><code>Attempt limit exceeded, please try after some time.</code></td></tr></tbody></table><h2 id="lastverifiedemail" tabindex="-1">lastVerifiedEmail <a class="header-anchor" href="#lastverifiedemail" aria-label="Permalink to &quot;lastVerifiedEmail&quot;">​</a></h2><div class="language-swift vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">swift</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">func</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> lastVerifiedEmail</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">revert</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">Bool</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">?</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> =</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> nil</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">) </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">async</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> throws</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> -&gt;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> JSON</span></span></code></pre></div><p>Returns the user&#39;s last verified e-mail as a <code>JSON</code> string (the current one, if it is verified). <code>revert: true</code> switches the account back to that e-mail, verified, and returns the updated profile.</p><table tabindex="0"><thead><tr><th>code</th><th>message</th></tr></thead><tbody><tr><td><code>NOT_EXISTS</code></td><td><code>User does not have a verified e-mail.</code></td></tr><tr><td><code>EXISTS</code></td><td><code>E-mail &quot;&lt;email&gt;&quot; is already a login ID in this project.</code></td></tr><tr><td><code>INVALID_REQUEST</code></td><td><code>Anonymous accounts cannot change their e-mail.</code></td></tr></tbody></table><h2 id="disableaccount" tabindex="-1">disableAccount <a class="header-anchor" href="#disableaccount" aria-label="Permalink to &quot;disableAccount&quot;">​</a></h2><div class="language-swift vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">swift</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">func</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> disableAccount</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">() </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">async</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> throws</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> -&gt;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> JSON</span></span></code></pre></div><p>Disables the signed-in user&#39;s account and logs out. The account&#39;s data is deleted after 90 days unless it is recovered. Returns the server&#39;s message, <code>&quot;SUCCESS: account has been disabled.&quot;</code></p><table tabindex="0"><thead><tr><th>code</th><th>message</th></tr></thead><tbody><tr><td><code>INVALID_REQUEST</code></td><td><code>Anonymous accounts cannot be disabled.</code></td></tr></tbody></table><h2 id="recoveraccount" tabindex="-1">recoverAccount <a class="header-anchor" href="#recoveraccount" aria-label="Permalink to &quot;recoverAccount&quot;">​</a></h2><div class="language-swift vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">swift</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">func</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> recoverAccount</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">redirect</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: JSON </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> false</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">) </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">async</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> throws</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> -&gt;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> String</span></span></code></pre></div><p>After <code>login</code> threw <code>USER_IS_DISABLED</code> on this object, e-mails a recovery link to the account. <code>redirect</code> is <code>false</code>, <code>true</code>, or a full URL string, where the link leads after the recovery: <code>recoverAccount(redirect: &quot;https://your.site/welcome-back&quot;)</code>. Returns <code>&quot;SUCCESS: Recovery e-mail has been sent.&quot;</code></p><table tabindex="0"><thead><tr><th>code</th><th>message</th></tr></thead><tbody><tr><td><code>INVALID_REQUEST</code></td><td><code>Least one signin attempt of disabled account is required.</code></td></tr><tr><td><code>INVALID_REQUEST</code></td><td><code>Argument should be type: &lt;boolean | string&gt;.</code></td></tr></tbody></table><h2 id="openidlogin" tabindex="-1">openIdLogin <a class="header-anchor" href="#openidlogin" aria-label="Permalink to &quot;openIdLogin&quot;">​</a></h2><div class="language-swift vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">swift</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">func</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> openIdLogin</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">token</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">String</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">id</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">String</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">merge</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: JSON</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">?</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> =</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> nil</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">template</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: JSON</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">?</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> =</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> nil</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">) </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">async</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> throws</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> -&gt;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> JSON</span></span></code></pre></div><p>Signs in through the OpenID logger <code>id</code> with a token from the provider, creating the account on first use. <code>merge: true</code> merges into an existing account with the same login ID; an array of attribute names (or one name) also copies those OpenID attributes. <code>template: [&quot;welcome&quot;: &quot;&lt;message_id&gt;&quot;]</code> uses an uploaded template for the welcome e-mail.</p><p>Returns <code>{&quot;userProfile&quot;: profile, &quot;openid&quot;: provider attributes}</code>. Can throw <code>MFA_REQUIRED</code>, <code>USER_IS_DISABLED</code> and <code>REQUEST_EXCEED</code> like <a href="#login">login</a>. See <a href="/authentication/openid.html">OpenID Login</a>.</p><table tabindex="0"><thead><tr><th>code</th><th>message</th></tr></thead><tbody><tr><td><code>ACCOUNT_EXISTS</code></td><td><code>The account already exists.</code> (retry with <code>merge</code>)</td></tr><tr><td><code>INVALID_REQUEST</code></td><td><code>The account needs to be confirmed.</code></td></tr><tr><td><code>EXISTS</code></td><td><code>The login ID of this OpenID account is already used by another account.</code></td></tr><tr><td><code>INVALID_PARAMETER</code></td><td><code>&quot;merge&quot; should be type: &lt;boolean | string[]&gt;.</code> / <code>&quot;merge&quot; array items should be type: &lt;string&gt;.</code></td></tr><tr><td><code>INVALID_PARAMETER</code></td><td><code>&quot;template&quot; should be type: &lt;object&gt;.</code> / <code>&quot;template.welcome&quot; should be a non-empty &lt;string&gt; (template message_id).</code></td></tr></tbody></table><h2 id="anonymouslogin" tabindex="-1">anonymousLogin <a class="header-anchor" href="#anonymouslogin" aria-label="Permalink to &quot;anonymousLogin&quot;">​</a></h2><div class="language-swift vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">swift</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">func</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> anonymousLogin</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">() </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">async</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> throws</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> -&gt;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> JSON</span></span></code></pre></div><p>Signs in with a temporary account (<code>anonymous: true</code>, access group <code>1</code>) and returns its profile. Returns the current account when this object already holds an anonymous session. Sends a keep-alive every 10 minutes while the object lives; the account is deleted 30 minutes after the last one, or at once on <code>logout</code>. See <a href="/authentication/anonymous.html">Anonymous Login</a>.</p><table tabindex="0"><thead><tr><th>code</th><th>message</th></tr></thead><tbody><tr><td><code>INVALID_REQUEST</code></td><td><code>Anonymous login is not enabled for this project.</code></td></tr><tr><td><code>INVALID_REQUEST</code></td><td><code>User limit exceeded.</code></td></tr><tr><td><code>INVALID_REQUEST</code></td><td><code>A user is already logged in. Log out first.</code></td></tr></tbody></table><h2 id="verifyanonymoussession" tabindex="-1">verifyAnonymousSession <a class="header-anchor" href="#verifyanonymoussession" aria-label="Permalink to &quot;verifyAnonymousSession&quot;">​</a></h2><div class="language-swift vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">swift</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">func</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> verifyAnonymousSession</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">() </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">async</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> throws</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> -&gt;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> JSON</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">?</span></span></code></pre></div><p>For a temporary account restored from <code>storage</code>: asks the server whether it still exists. Returns the profile, or <code>nil</code> (after signing out) when the account was deleted. Any other signed-in user is returned as is, without a request; signed out returns <code>nil</code>.</p><h2 id="setupmfa" tabindex="-1">setupMFA <a class="header-anchor" href="#setupmfa" aria-label="Permalink to &quot;setupMFA&quot;">​</a></h2><div class="language-swift vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">swift</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">func</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> setupMFA</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">issuer</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">String</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">?</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> =</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> nil</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">accountName</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">String</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">?</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> =</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> nil</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">) </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">async</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> throws</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> -&gt;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> JSON</span></span></code></pre></div><p>Starts two-step login setup. Returns <code>{&quot;secret&quot;: String, &quot;uri&quot;: String}</code>: show <code>uri</code> (<code>otpauth://...</code>) as a QR code, or <code>secret</code> for typing in. <code>issuer</code> defaults to the project name, <code>accountName</code> to the user&#39;s e-mail. Follow with <a href="#enablemfa">enableMFA</a>.</p><h2 id="enablemfa" tabindex="-1">enableMFA <a class="header-anchor" href="#enablemfa" aria-label="Permalink to &quot;enableMFA&quot;">​</a></h2><div class="language-swift vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">swift</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">func</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> enableMFA</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">code</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">String</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">) </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">async</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> throws</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> -&gt;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> String</span></span></code></pre></div><p>Checks a code from the app and turns two-step login on. Returns <code>&quot;SUCCESS: MFA has been enabled.&quot;</code></p><table tabindex="0"><thead><tr><th>code</th><th>message</th></tr></thead><tbody><tr><td><code>INVALID_CODE</code></td><td><code>Incorrect authenticator code.</code> (nothing changed)</td></tr><tr><td><code>INVALID_REQUEST</code></td><td><code>Call setupMFA() first.</code></td></tr><tr><td><code>INVALID_PARAMETER</code></td><td><code>&quot;code&quot; should be the 6 digit code from the authenticator app.</code></td></tr><tr><td><code>REQUEST_EXCEED</code></td><td><code>Too many attempts. Please try again later.</code></td></tr></tbody></table><h2 id="disablemfa" tabindex="-1">disableMFA <a class="header-anchor" href="#disablemfa" aria-label="Permalink to &quot;disableMFA&quot;">​</a></h2><div class="language-swift vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">swift</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">func</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> disableMFA</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">() </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">async</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> throws</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> -&gt;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> String</span></span></code></pre></div><p>Turns two-step login off. Returns <code>&quot;SUCCESS: MFA has been disabled.&quot;</code></p><h2 id="getmfastatus" tabindex="-1">getMFAStatus <a class="header-anchor" href="#getmfastatus" aria-label="Permalink to &quot;getMFAStatus&quot;">​</a></h2><div class="language-swift vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">swift</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">func</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> getMFAStatus</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">() </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">async</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> throws</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> -&gt;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> JSON</span></span></code></pre></div><p>Returns <code>{&quot;enabled&quot;: Bool}</code>.</p><p><code>setupMFA</code>, <code>enableMFA</code>, <code>disableMFA</code> and <code>getMFAStatus</code> need a signed-in user and throw <code>INVALID_REQUEST</code> with a message starting with <code>Anonymous accounts cannot</code> on an anonymous account.</p>`,100)])])}const g=s(d,[["render",o]]);export{k as __pageData,g as default};
